inserted AS (
  INSERT INTO public.quiz_questions
    (category, question, answer_a, answer_b, answer_c, answer_d,
     correct_index, source_url, active, source_key)
  SELECT i.category, i.question, i.answer_a, i.answer_b, i.answer_c, i.answer_d,
         i.correct_index, i.source_url, i.active, i.source_key
  FROM incoming i
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.quiz_questions q
    WHERE lower(regexp_replace(trim(q.question), E'\\\\s+', ' ', 'g')) =
          lower(regexp_replace(trim(i.question), E'\\\\s+', ' ', 'g'))
  )
  AND NOT EXISTS (
    SELECT 1 FROM public.quiz_questions q WHERE q.source_key = i.source_key
  )
  RETURNING id
)
SELECT count(*) AS inserted_questions FROM inserted;
